/* Task: allocation — dense matrix multiplication (GEMM) kernel.
 * Deliberately HLS-incompatible, in the way HeteroGen's inputs are:
 *  - matrices heap-allocated with malloc/free
 *  - kernel takes raw pointers (float *A) instead of fixed-size arrays
 *  - loop bounds are the runtime variable n, not a compile-time constant
 * Behaviour: C = A * B for n x n matrices, prints a checksum.
 * Test inputs are generated by the harness (seed sweep), not baked in.
 */
#include <stdio.h>
#include <stdlib.h>

void matmul(float *A, float *B, float *C, int n) {
    int i, j, k;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            float sum = 0.0f;
            for (k = 0; k < n; k++) {
                sum += A[i * n + k] * B[k * n + j];
            }
            C[i * n + j] = sum;
        }
    }
}

static unsigned int rng_state = 1;
static float next_rand(void) {
    rng_state = rng_state * 1103515245u + 12345u;
    return (float)((rng_state >> 16) & 0xFF) / 255.0f;
}

int main(int argc, char **argv) {
    int n = 8;
    if (argc > 1) {
        n = atoi(argv[1]);
    }
    if (argc > 2) {
        rng_state = (unsigned int)atoi(argv[2]);
    }
    float *A = (float *)malloc(n * n * sizeof(float));
    float *B = (float *)malloc(n * n * sizeof(float));
    float *C = (float *)malloc(n * n * sizeof(float));
    int i;
    for (i = 0; i < n * n; i++) {
        A[i] = next_rand();
        B[i] = next_rand();
    }
    matmul(A, B, C, n);
    double checksum = 0.0;
    for (i = 0; i < n * n; i++) {
        checksum += C[i];
    }
    printf("checksum=%.6f\n", checksum);
    free(A);
    free(B);
    free(C);
    return 0;
}
